CustomField.formula:
IF(
/* First condition: Delivery Date is less than 22/09/2024 */
Order.Delivery_Date__c < DATE(2024, 9, 22),
/* Use the original logic */
IF(
NOT(ISNULL(Recycled_KG_from_Weights__c)),
Recycled_KG_from_Weights__c,
Quantity *  PricebookEntry.Product2.Recycle_KG__c
),

/* Second condition: Delivery Date is on or after 22/09/2024 */
IF(
/* Check if Recycled_KG_from_Weights__c is greater than 0 */
Recycled_KG_from_Weights__c > 0,
Recycled_KG_from_Weights__c,

/* If Recycled_KG_from_Weights__c is blank or zero, apply Fall_Back_Weight_Type__c logic */
IF(
TEXT(Order.Account.Fall_Back_Weight_Type__c) = "No Weight",
/* Fall Back Weight Type is "No Weight" */
0,

IF(
/* Check if it's a Company Average Weight and AD_KG__c > 0 */
TEXT(Order.Account.Fall_Back_Weight_Type__c) = "Company Average Weight"
&& PricebookEntry.Product2.Recycle_KG__c > 0,
/* Apply Company Average Weight if Recycle_KG__c is greater than 0 */
Quantity * PricebookEntry.Product2.Estimated_Weight__c,

/* Default value if none of the conditions match */
Quantity * PricebookEntry.Product2.Recycle_KG__c
)
)
)
)
